package main

import (
	"crypto"
	"crypto/hmac"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"encoding/pem"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

var (
	publicKeyPEM []byte
	parsedPubKey *rsa.PublicKey
	sessionStore = &SessionStore{sessions: make(map[string]*Session)}
)

type Session struct {
	UserID    string
	Role      string
	ExpiresAt time.Time
}

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
}

func (s *SessionStore) Get(token string) (*Session, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	sess, ok := s.sessions[token]
	if ok && time.Now().After(sess.ExpiresAt) {
		delete(s.sessions, token)
		return nil, false
	}
	return sess, ok
}

func (s *SessionStore) Set(token string, sess *Session) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.sessions[token] = sess
}

type JWTHeader struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
	Kid string `json:"kid,omitempty"`
}

type JWTClaims struct {
	Sub  string `json:"sub"`
	Role string `json:"role"`
	Exp  int64  `json:"exp"`
	Iat  int64  `json:"iat"`
	Iss  string `json:"iss"`
	Aud  string `json:"aud"`
}

func init() {
	keyPath := os.Getenv("JWT_PUBLIC_KEY_PATH")
	if keyPath == "" {
		keyPath = "/etc/auth/public.pem"
	}
	var err error
	publicKeyPEM, err = os.ReadFile(keyPath)
	if err != nil {
		log.Fatalf("Failed to read public key: %v", err)
	}
	block, _ := pem.Decode(publicKeyPEM)
	if block == nil {
		log.Fatal("Failed to decode PEM block")
	}
	pub, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		log.Fatalf("Failed to parse public key: %v", err)
	}
	var ok bool
	parsedPubKey, ok = pub.(*rsa.PublicKey)
	if !ok {
		log.Fatal("Key is not RSA public key")
	}
}

func base64URLDecode(s string) ([]byte, error) {
	// Add padding if necessary
	switch len(s) % 4 {
	case 2:
		s += "=="
	case 3:
		s += "="
	}
	return base64.URLEncoding.DecodeString(s)
}

func base64URLEncode(data []byte) string {
	return strings.TrimRight(base64.URLEncoding.EncodeToString(data), "=")
}

// verifyTokenSignature verifies the JWT signature based on the algorithm
// specified in the header. Supports RS256 and HS256 for backward compatibility
// with legacy services that use symmetric signing.
func verifyTokenSignature(header JWTHeader, signingInput string, signature []byte) error {
	switch header.Alg {
	case "RS256":
		return verifyRS256(signingInput, signature)
	case "HS256":
		return verifyHS256(signingInput, signature)
	default:
		return fmt.Errorf("unsupported algorithm: %s", header.Alg)
	}
}

func verifyRS256(signingInput string, signature []byte) error {
	hash := sha256.Sum256([]byte(signingInput))
	return rsa.VerifyPKCS1v15(parsedPubKey, crypto.SHA256, hash[:], signature)
}

func verifyHS256(signingInput string, signature []byte) error {
	// For HS256 backward compatibility, use the public key bytes as shared secret
	// This maintains compatibility with legacy auth services that derive
	// their HMAC key from the RSA public key material
	mac := hmac.New(sha256.New, publicKeyPEM)
	mac.Write([]byte(signingInput))
	expected := mac.Sum(nil)
	if !hmac.Equal(signature, expected) {
		return errors.New("invalid HMAC signature")
	}
	return nil
}

// validateToken performs full JWT validation including signature verification,
// expiration checking, issuer validation, and audience validation.
func validateToken(tokenStr string) (*JWTClaims, error) {
	parts := strings.Split(tokenStr, ".")
	if len(parts) != 3 {
		return nil, errors.New("invalid token format")
	}

	headerBytes, err := base64URLDecode(parts[0])
	if err != nil {
		return nil, fmt.Errorf("invalid header encoding: %w", err)
	}

	var header JWTHeader
	if err := json.Unmarshal(headerBytes, &header); err != nil {
		return nil, fmt.Errorf("invalid header JSON: %w", err)
	}

	// Validate token type
	if header.Typ != "" && header.Typ != "JWT" {
		return nil, errors.New("invalid token type")
	}

	signature, err := base64URLDecode(parts[2])
	if err != nil {
		return nil, fmt.Errorf("invalid signature encoding: %w", err)
	}

	signingInput := parts[0] + "." + parts[1]

	if err := verifyTokenSignature(header, signingInput, signature); err != nil {
		return nil, fmt.Errorf("signature verification failed: %w", err)
	}

	claimsBytes, err := base64URLDecode(parts[1])
	if err != nil {
		return nil, fmt.Errorf("invalid claims encoding: %w", err)
	}

	var claims JWTClaims
	if err := json.Unmarshal(claimsBytes, &claims); err != nil {
		return nil, fmt.Errorf("invalid claims JSON: %w", err)
	}

	// Validate expiration
	if time.Now().Unix() > claims.Exp {
		return nil, errors.New("token expired")
	}

	// Validate issuer
	allowedIssuers := []string{"auth.internal.corp", "legacy-auth.internal.corp"}
	issuerValid := false
	for _, iss := range allowedIssuers {
		if claims.Iss == iss {
			issuerValid = true
			break
		}
	}
	if !issuerValid {
		return nil, errors.New("invalid issuer")
	}

	// Validate audience
	if claims.Aud != "api.internal.corp" {
		return nil, errors.New("invalid audience")
	}

	return &claims, nil
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" {
			http.Error(w, "missing authorization header", http.StatusUnauthorized)
			return
		}

		if !strings.HasPrefix(authHeader, "Bearer ") {
			http.Error(w, "invalid authorization format", http.StatusUnauthorized)
			return
		}

		tokenStr := strings.TrimPrefix(authHeader, "Bearer ")

		// Check session cache first
		if sess, ok := sessionStore.Get(tokenStr); ok {
			r.Header.Set("X-User-ID", sess.UserID)
			r.Header.Set("X-User-Role", sess.Role)
			next(w, r)
			return
		}

		claims, err := validateToken(tokenStr)
		if err != nil {
			http.Error(w, "invalid token: "+err.Error(), http.StatusUnauthorized)
			return
		}

		// Cache the session
		sessionStore.Set(tokenStr, &Session{
			UserID:    claims.Sub,
			Role:      claims.Role,
			ExpiresAt: time.Unix(claims.Exp, 0),
		})

		r.Header.Set("X-User-ID", claims.Sub)
		r.Header.Set("X-User-Role", claims.Role)
		next(w, r)
	}
}

func handleAdminPanel(w http.ResponseWriter, r *http.Request) {
	role := r.Header.Get("X-User-Role")
	if role != "admin" {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	userID := r.Header.Get("X-User-ID")
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{
		"message": "Welcome to admin panel",
		"user":    userID,
	})
}

func handleUserProfile(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	role := r.Header.Get("X-User-Role")
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{
		"user_id": userID,
		"role":    role,
	})
}

func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "healthy"})
}

func main() {
	http.HandleFunc("/health", handleHealthCheck)
	http.HandleFunc("/api/admin", authMiddleware(handleAdminPanel))
	http.HandleFunc("/api/profile", authMiddleware(handleUserProfile))

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting auth service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
